  "展开全部": ["Show all", "Mostrar todo", "すべて表示", "Tout afficher", "Alle anzeigen", "عرض الكل", "Xem tất cả", "सभी दिखाएँ", "展開全部"],
  "收起": ["Collapse", "Contraer", "折りたたむ", "Réduire", "Einklappen", "طيّ", "Thu gọn", "संकुचित करें", "收起"],
